import type { FoldKind, Vec } from './types.ts';

// The 24 axis-aligned rotations as 3x3 integer matrices (row-major), generated by closure.
// R maps room space to view space (v = R * c). Rows of R are the room-space directions of
// the view axes: right = row 0, down = row 1, away = row 2.

type Mat = number[];

function mul(a: Mat, b: Mat): Mat {
  const r: Mat = new Array(9).fill(0);
  for (let i = 0; i < 3; i++)
    for (let j = 0; j < 3; j++) {
      let s = 0;
      for (let k = 0; k < 3; k++) s += a[i * 3 + k] * b[k * 3 + j];
      r[i * 3 + j] = s;
    }
  return r;
}

// View-space quarter turns. rollR: (x,y,z) -> (-y, x, z); pitchB: (x,y,z) -> (x, z, -y)
const ROLL_R: Mat = [0, -1, 0, 1, 0, 0, 0, 0, 1];
const ROLL_L: Mat = [0, 1, 0, -1, 0, 0, 0, 0, 1];
const PITCH_B: Mat = [1, 0, 0, 0, 0, 1, 0, -1, 0];
const PITCH_A: Mat = [1, 0, 0, 0, 0, -1, 0, 1, 0];

export const FOLD_MATS: Record<FoldKind, Mat> = { rollR: ROLL_R, rollL: ROLL_L, pitchB: PITCH_B, pitchA: PITCH_A };
export const FOLD_KINDS: FoldKind[] = ['rollL', 'rollR', 'pitchA', 'pitchB'];

const IDENT: Mat = [1, 0, 0, 0, 1, 0, 0, 0, 1];
export const MATS: Mat[] = [IDENT];
const keyOf = (m: Mat): string => m.join(',');
const index = new Map<string, number>([[keyOf(IDENT), 0]]);
for (let i = 0; i < MATS.length; i++) {
  for (const k of FOLD_KINDS) {
    const n = mul(FOLD_MATS[k], MATS[i]);
    const key = keyOf(n);
    if (!index.has(key)) {
      index.set(key, MATS.length);
      MATS.push(n);
    }
  }
}

export const FOLD_TABLE: Record<FoldKind, number[]> = { rollL: [], rollR: [], pitchA: [], pitchB: [] };
for (let i = 0; i < MATS.length; i++) {
  for (const k of FOLD_KINDS) FOLD_TABLE[k][i] = index.get(keyOf(mul(FOLD_MATS[k], MATS[i])))!;
}

export const RIGHT: Vec[] = MATS.map((m) => [m[0], m[1], m[2]] as const);
export const DOWN: Vec[] = MATS.map((m) => [m[3], m[4], m[5]] as const);
export const AWAY: Vec[] = MATS.map((m) => [m[6], m[7], m[8]] as const);

export function inverseKind(k: FoldKind): FoldKind {
  return k === 'rollL' ? 'rollR' : k === 'rollR' ? 'rollL' : k === 'pitchA' ? 'pitchB' : 'pitchA';
}
